import { useState, useEffect, useCallback } from 'react';
import { trackEvent } from '../utils/analytics';
import { TABS, getAllTabIds } from '../components/FinancialFormulaSuite/tabRegistry';

const STORAGE_KEY = 'financial-formula-last-tab';
const DEFAULT_TAB = 'home';

/**
 * Hook for managing Financial Formula Suite state and analytics
 *
 * Provides:
 * - Tab selection and persistence
 * - Analytics tracking
 * - Tab registry access
 * - Dynamic tab registration (for future extensibility)
 */
export default function useFinancialFormulaSuite() {
  const [selectedTab, setSelectedTab] = useState(() => {
    // Initialize from localStorage or default
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      const validIds = getAllTabIds();
      return saved && validIds.includes(saved) ? saved : DEFAULT_TAB;
    } catch {
      return DEFAULT_TAB;
    }
  });

  const [registeredTabs, setRegisteredTabs] = useState(TABS);

  // Track app opening on mount
  useEffect(() => {
    trackEvent('tool_open', {
      tool: 'financial_formula_suite',
      initial_tab: selectedTab
    });
  }, []);

  // Persist selected tab to localStorage
  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, selectedTab);
    } catch (error) {
      console.warn('Failed to save tab to localStorage:', error);
    }
  }, [selectedTab]);

  // Select tab with analytics tracking
  const selectTab = useCallback((tabId) => {
    if (tabId === selectedTab) return;

    const validIds = getAllTabIds();
    if (!validIds.includes(tabId)) {
      console.warn(`Invalid tab ID: ${tabId}`);
      return;
    }

    setSelectedTab(tabId);

    // Track tab change
    trackEvent('tab_change', {
      tool: 'financial_formula_suite',
      from_tab: selectedTab,
      to_tab: tabId
    });
  }, [selectedTab]);

  // Dynamic tab registration (for future extensibility)
  const registerTab = useCallback((tabConfig) => {
    if (!tabConfig.id || !tabConfig.title || !tabConfig.load) {
      console.error('Invalid tab config. Required: id, title, load');
      return false;
    }

    setRegisteredTabs(current => {
      const exists = current.some(tab => tab.id === tabConfig.id);
      if (exists) {
        console.warn(`Tab with ID ${tabConfig.id} already exists`);
        return current;
      }
      return [...current, tabConfig];
    });

    trackEvent('tab_registered', {
      tool: 'financial_formula_suite',
      tab_id: tabConfig.id
    });

    return true;
  }, []);

  // Navigate to next/previous tab (for keyboard navigation)
  const navigateTab = useCallback((direction) => {
    const currentIndex = registeredTabs.findIndex(tab => tab.id === selectedTab);
    let newIndex;

    if (direction === 'next') {
      newIndex = (currentIndex + 1) % registeredTabs.length;
    } else if (direction === 'prev') {
      newIndex = currentIndex === 0 ? registeredTabs.length - 1 : currentIndex - 1;
    } else if (direction === 'first') {
      newIndex = 0;
    } else if (direction === 'last') {
      newIndex = registeredTabs.length - 1;
    } else {
      return;
    }

    selectTab(registeredTabs[newIndex].id);
  }, [registeredTabs, selectedTab, selectTab]);

  return {
    selectedTab,
    selectTab,
    tabs: registeredTabs,
    registerTab,
    navigateTab,
    // Utility getters
    selectedTabData: registeredTabs.find(tab => tab.id === selectedTab),
    tabCount: registeredTabs.length
  };
}
