import React from 'react';
import { useTheme } from '../context/ThemeContext';
import { Settings as SettingsIcon, Monitor, Sun, Moon } from 'lucide-react';

const Settings = () => {
  const { theme, toggleTheme } = useTheme();

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex items-center space-x-3">
        <SettingsIcon className="w-8 h-8 text-indigo-600" />
        <h1 className="text-3xl font-bold">Settings</h1>
      </div>

      {/* Settings Content */}
      <div className="content-area space-y-8">
        {/* Theme Settings */}
        <div className="bg-white dark:bg-gray-800 rounded-lg p-6 shadow-sm">
          <h2 className="text-2xl font-semibold mb-4 flex items-center">
            <Monitor className="w-6 h-6 text-blue-500 mr-2" />
            Appearance
          </h2>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Theme Preference
              </label>
              <div className="flex items-center space-x-4">
                <button
                  onClick={toggleTheme}
                  className={`flex items-center space-x-2 px-4 py-2 rounded-lg border transition-colors ${
                    theme === 'light'
                      ? 'bg-blue-50 border-blue-200 text-blue-700 dark:bg-blue-900/20 dark:border-blue-800 dark:text-blue-300'
                      : 'bg-gray-50 border-gray-200 text-gray-700 hover:bg-gray-100 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-600'
                  }`}
                >
                  <Sun className="w-4 h-4" />
                  <span>Light</span>
                </button>
                <button
                  onClick={toggleTheme}
                  className={`flex items-center space-x-2 px-4 py-2 rounded-lg border transition-colors ${
                    theme === 'dark'
                      ? 'bg-blue-50 border-blue-200 text-blue-700 dark:bg-blue-900/20 dark:border-blue-800 dark:text-blue-300'
                      : 'bg-gray-50 border-gray-200 text-gray-700 hover:bg-gray-100 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-600'
                  }`}
                >
                  <Moon className="w-4 h-4" />
                  <span>Dark</span>
                </button>
              </div>
              <p className="text-sm text-gray-600 dark:text-gray-400 mt-2">
                Choose between light and dark appearance
              </p>
            </div>
          </div>
        </div>

        {/* Application Info */}
        <div className="bg-white dark:bg-gray-800 rounded-lg p-6 shadow-sm">
          <h2 className="text-2xl font-semibold mb-4">About</h2>
          <div className="space-y-3 text-gray-600 dark:text-gray-400">
            <p>
              <strong>AllInOne Dashboard</strong> - Your comprehensive productivity hub
            </p>
            <p>
              Combining calculators, games, and productivity tools in one seamless interface.
            </p>
            <p>
              Built with React and designed for modern workflows.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;
