import React, { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const OptionChart = ({ data, mode }) => {
  const [selectedGreek, setSelectedGreek] = useState('delta');
  const [chartType, setChartType] = useState('prices'); // 'prices' or 'greeks'

  if (!data || data.length === 0) return null;

  const greekOptions = [
    { key: 'delta', label: 'Delta', format: (val) => val.toFixed(3) },
    { key: 'gamma', label: 'Gamma', format: (val) => val.toFixed(4) },
    { key: 'theta', label: 'Theta', format: (val) => val.toFixed(3) },
    { key: 'vega', label: 'Vega', format: (val) => val.toFixed(3) },
    { key: 'rho', label: 'Rho', format: (val) => val.toFixed(3) }
  ];

  // Prepare chart data
  const chartData = data.map((row, index) => ({
    index: index,
    xValue: mode === 'strike' ? row.strike : row.expiration,
    callPrice: row.call.price,
    putPrice: row.put.price,
    callDelta: row.call.delta,
    putDelta: row.put.delta,
    callGamma: row.call.gamma,
    putGamma: row.put.gamma,
    callTheta: row.call.theta,
    putTheta: row.put.theta,
    callVega: row.call.vega,
    putVega: row.put.vega,
    callRho: row.call.rho,
    putRho: row.put.rho
  }));

  const formatXAxisLabel = (value) => {
    return mode === 'strike' ? `$${value}` : `${value}y`;
  };

  const formatTooltipValue = (value, name) => {
    if (name.includes('Price')) {
      return [`$${value.toFixed(2)}`, name];
    }
    return [value.toFixed(4), name];
  };

  return (
    <div className="space-y-4">
      {/* Chart Type Toggle */}
      <div className="flex items-center justify-between">
        <div className="flex space-x-2">
          <button
            onClick={() => setChartType('prices')}
            className={`px-3 py-1 rounded text-sm transition-colors ${
              chartType === 'prices'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300'
            }`}
          >
            Option Prices
          </button>
          <button
            onClick={() => setChartType('greeks')}
            className={`px-3 py-1 rounded text-sm transition-colors ${
              chartType === 'greeks'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300'
            }`}
          >
            Greeks
          </button>
        </div>

        {/* Greek Selector (only shown when greeks chart is active) */}
        {chartType === 'greeks' && (
          <select
            value={selectedGreek}
            onChange={(e) => setSelectedGreek(e.target.value)}
            className="px-3 py-1 border border-gray-300 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
          >
            {greekOptions.map(greek => (
              <option key={greek.key} value={greek.key}>
                {greek.label}
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Chart */}
      <div className="h-80">
        <ResponsiveContainer width="100%" height="100%">
          {chartType === 'prices' ? (
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" className="opacity-30" />
              <XAxis
                dataKey="xValue"
                tickFormatter={formatXAxisLabel}
                label={{
                  value: mode === 'strike' ? 'Strike Price' : 'Time to Expiration',
                  position: 'insideBottom',
                  offset: -5
                }}
              />
              <YAxis
                label={{
                  value: 'Option Price ($)',
                  angle: -90,
                  position: 'insideLeft'
                }}
                tickFormatter={(value) => `$${value.toFixed(1)}`}
              />
              <Tooltip
                formatter={formatTooltipValue}
                labelFormatter={(value) => `${mode === 'strike' ? 'Strike' : 'Expiration'}: ${formatXAxisLabel(value)}`}
                contentStyle={{
                  backgroundColor: 'rgba(255, 255, 255, 0.95)',
                  border: '1px solid #e5e7eb',
                  borderRadius: '6px'
                }}
              />
              <Legend />
              <Line
                type="monotone"
                dataKey="callPrice"
                stroke="#10b981"
                strokeWidth={2}
                name="Call Price"
                dot={{ fill: '#10b981', strokeWidth: 2, r: 3 }}
                activeDot={{ r: 5 }}
              />
              <Line
                type="monotone"
                dataKey="putPrice"
                stroke="#ef4444"
                strokeWidth={2}
                name="Put Price"
                dot={{ fill: '#ef4444', strokeWidth: 2, r: 3 }}
                activeDot={{ r: 5 }}
              />
            </LineChart>
          ) : (
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" className="opacity-30" />
              <XAxis
                dataKey="xValue"
                tickFormatter={formatXAxisLabel}
                label={{
                  value: mode === 'strike' ? 'Strike Price' : 'Time to Expiration',
                  position: 'insideBottom',
                  offset: -5
                }}
              />
              <YAxis
                label={{
                  value: `${greekOptions.find(g => g.key === selectedGreek)?.label} Value`,
                  angle: -90,
                  position: 'insideLeft'
                }}
                tickFormatter={(value) => value.toFixed(3)}
              />
              <Tooltip
                formatter={formatTooltipValue}
                labelFormatter={(value) => `${mode === 'strike' ? 'Strike' : 'Expiration'}: ${formatXAxisLabel(value)}`}
                contentStyle={{
                  backgroundColor: 'rgba(255, 255, 255, 0.95)',
                  border: '1px solid #e5e7eb',
                  borderRadius: '6px'
                }}
              />
              <Legend />
              <Line
                type="monotone"
                dataKey={`call${selectedGreek.charAt(0).toUpperCase() + selectedGreek.slice(1)}`}
                stroke="#10b981"
                strokeWidth={2}
                name={`Call ${greekOptions.find(g => g.key === selectedGreek)?.label}`}
                dot={{ fill: '#10b981', strokeWidth: 2, r: 3 }}
                activeDot={{ r: 5 }}
              />
              <Line
                type="monotone"
                dataKey={`put${selectedGreek.charAt(0).toUpperCase() + selectedGreek.slice(1)}`}
                stroke="#ef4444"
                strokeWidth={2}
                name={`Put ${greekOptions.find(g => g.key === selectedGreek)?.label}`}
                dot={{ fill: '#ef4444', strokeWidth: 2, r: 3 }}
                activeDot={{ r: 5 }}
              />
            </LineChart>
          )}
        </ResponsiveContainer>
      </div>

      {/* Chart Description */}
      <div className="text-xs text-gray-600 dark:text-gray-400 bg-gray-50 dark:bg-gray-800 rounded p-3">
        {chartType === 'prices' ? (
          <p>
            <strong>Option Prices:</strong> This chart shows how call (green) and put (red) option prices change across different {mode === 'strike' ? 'strike prices' : 'expiration times'}.
            Call options typically increase in value as strike prices decrease, while put options increase as strike prices increase.
          </p>
        ) : (
          <p>
            <strong>{greekOptions.find(g => g.key === selectedGreek)?.label}:</strong> This chart shows how the {selectedGreek} values change for both call and put options.
            {selectedGreek === 'delta' && 'Delta measures price sensitivity to the underlying asset price changes.'}
            {selectedGreek === 'gamma' && 'Gamma measures the rate of change of delta.'}
            {selectedGreek === 'theta' && 'Theta measures time decay - how option value decreases over time.'}
            {selectedGreek === 'vega' && 'Vega measures sensitivity to volatility changes.'}
            {selectedGreek === 'rho' && 'Rho measures sensitivity to interest rate changes.'}
          </p>
        )}
      </div>
    </div>
  );
};

export default OptionChart;
