/**
 * SearchBar.jsx
 * Global search bar component for the navbar that allows searching across all tools
 * Updated with glassy theme to match the modern navbar design
 */

import React, { useState, useEffect, useRef } from 'react';
import { Search, X } from 'lucide-react';
import { TOOL_CATALOG } from '../utils/toolCategories';
import { trackEvent } from '../utils/analytics';

const SearchBar = ({ onNavigate }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [filteredTools, setFilteredTools] = useState([]);
  const [isOpen, setIsOpen] = useState(false);
  const searchRef = useRef(null);
  const dropdownRef = useRef(null);

  // Search functionality
  useEffect(() => {
    if (searchQuery.trim() === '') {
      setFilteredTools([]);
      setIsOpen(false);
      return;
    }

    const query = searchQuery.toLowerCase();
    const results = TOOL_CATALOG.filter(tool => {
      return (
        (tool.name || tool.title || '').toLowerCase().includes(query) ||
        tool.description.toLowerCase().includes(query) ||
        tool.category.toLowerCase().includes(query) ||
        (tool.keywords && tool.keywords.some(keyword => keyword.toLowerCase().includes(query)))
      );
    }).slice(0, 6); // Limit to 6 results for navbar dropdown

    setFilteredTools(results);
    setIsOpen(results.length > 0);
  }, [searchQuery]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (searchRef.current && !searchRef.current.contains(event.target) &&
          dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleToolSelect = (tool) => {
    trackEvent('search', 'tool_selected', tool.name || tool.title);
    const categoryId = tool.categoryId || tool.category?.toLowerCase().replace(/\s+/g, '-');
    const toolId = tool.id || tool.toolId;
    onNavigate(categoryId, toolId);
    setSearchQuery('');
    setIsOpen(false);
  };

  const clearSearch = () => {
    setSearchQuery('');
    setIsOpen(false);
  };

  return (
    <div className="relative">
      {/* Search Input with Glass Theme */}
      <div className="search-focus-ring relative">
        <input
          ref={searchRef}
          type="text"
          placeholder="Search tools..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-64 px-4 py-2 pl-10 pr-10 rounded-xl glass-secondary backdrop-blur-xl
                     border border-white/10 dark:border-white/5
                     text-black dark:text-white
                     placeholder-gray-500 dark:placeholder-gray-400
                     focus:outline-none focus:border-white/20 dark:focus:border-white/10
                     transition-all duration-300 hover:border-white/15 dark:hover:border-white/8"
        />
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-500 dark:text-gray-400" />
        {searchQuery && (
          <button
            onClick={clearSearch}
            className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1 rounded-full
                       hover:bg-white/10 dark:hover:bg-white/5 transition-colors duration-200"
          >
            <X className="w-3 h-3 text-gray-500 dark:text-gray-400" />
          </button>
        )}
      </div>

      {/* Search Results Dropdown with Enhanced Glass Theme */}
      {isOpen && (
        <div
          ref={dropdownRef}
          className="absolute top-full left-0 right-0 mt-2 glass-primary backdrop-blur-xl
                     border border-white/10 dark:border-white/5 rounded-xl shadow-2xl z-50
                     max-h-80 overflow-y-auto"
        >
          {filteredTools.map((tool, index) => {
            const IconComponent = tool.icon;
            return (
              <button
                key={tool.id || index}
                onClick={() => handleToolSelect(tool)}
                className="w-full text-left px-4 py-3 hover:glass-secondary transition-all duration-200
                           border-b border-white/5 dark:border-white/3 last:border-b-0
                           hover:backdrop-blur-xl group"
              >
                <div className="flex items-center space-x-3">
                  {IconComponent && <IconComponent className="w-5 h-5 text-green-400" />}
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-gray-900 dark:text-gray-100 truncate group-hover:text-green-400 transition-colors">
                      {tool.name || tool.title}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400 truncate">
                      {tool.description}
                    </p>
                  </div>
                  <span className="text-xs px-2 py-1 rounded-full glass-secondary border border-white/10 dark:border-white/5
                                   text-gray-600 dark:text-gray-300 bg-white/5 dark:bg-white/3">
                    {tool.category}
                  </span>
                </div>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default SearchBar;
