/**
 * ModulePage.jsx
 * Reusable component for module/tool category pages
 * Handles common functionality: module grid, card layout, navigation, etc.
 */

import React, { useState, useEffect } from 'react';
import { trackEvent } from '../utils/analytics';

const ModulePage = ({
  title,
  icon: IconComponent,
  modules,
  searchNavigation,
  colorTheme,
  eventPrefix,
  buttonText = "Launch Tool"
}) => {
  const [activeModule, setActiveModule] = useState(null);

  // Color theme mapping - ensures Tailwind includes these classes
  const colorThemes = {
    blue: {
      border: 'border-blue-200 dark:border-blue-800',
      iconBg: 'bg-blue-100 dark:bg-blue-900/30',
      iconText: 'text-blue-600',
      badgeBg: 'bg-blue-100 dark:bg-blue-900/30',
      badgeText: 'text-blue-800 dark:text-blue-200',
      button: 'bg-blue-600 hover:bg-blue-700',
      headerIcon: 'text-blue-600',
      glow: 'glow-blue'
    },
    purple: {
      border: 'border-purple-200 dark:border-purple-800',
      iconBg: 'bg-purple-100 dark:bg-purple-900/30',
      iconText: 'text-purple-600',
      badgeBg: 'bg-purple-100 dark:bg-purple-900/30',
      badgeText: 'text-purple-800 dark:text-purple-200',
      button: 'bg-purple-600 hover:bg-purple-700',
      headerIcon: 'text-purple-600',
      glow: 'glow-purple'
    },
    red: {
      border: 'border-red-200 dark:border-red-800',
      iconBg: 'bg-red-100 dark:bg-red-900/30',
      iconText: 'text-red-600',
      badgeBg: 'bg-red-100 dark:bg-red-900/30',
      badgeText: 'text-red-800 dark:text-red-200',
      button: 'bg-red-600 hover:bg-red-700',
      headerIcon: 'text-red-600',
      glow: 'glow-red'
    },
    yellow: {
      border: 'border-yellow-200 dark:border-yellow-800',
      iconBg: 'bg-yellow-100 dark:bg-yellow-900/30',
      iconText: 'text-yellow-600',
      badgeBg: 'bg-yellow-100 dark:bg-yellow-900/30',
      badgeText: 'text-yellow-800 dark:text-yellow-200',
      button: 'bg-yellow-600 hover:bg-yellow-700',
      headerIcon: 'text-yellow-600',
      glow: 'glow-yellow'
    },
    green: {
      border: 'border-green-200 dark:border-green-800',
      iconBg: 'bg-green-100 dark:bg-green-900/30',
      iconText: 'text-green-600',
      badgeBg: 'bg-green-100 dark:bg-green-900/30',
      badgeText: 'text-green-800 dark:text-green-200',
      button: 'bg-green-600 hover:bg-green-700',
      headerIcon: 'text-green-600',
      glow: 'glow-green'
    },
    orange: {
      border: 'border-orange-200 dark:border-orange-800',
      iconBg: 'bg-orange-100 dark:bg-orange-900/30',
      iconText: 'text-orange-600',
      badgeBg: 'bg-orange-100 dark:bg-orange-900/30',
      badgeText: 'text-orange-800 dark:text-orange-200',
      button: 'bg-orange-600 hover:bg-orange-700',
      headerIcon: 'text-orange-600',
      glow: 'glow-orange'
    }
  };

  const theme = colorThemes[colorTheme] || colorThemes.blue;

  // Handle opening a module
  const openModule = (moduleId) => {
    const module = modules.find(m => m.id === moduleId);
    if (module && module.status === 'available') {
      setActiveModule(module);
      trackEvent(`${eventPrefix}_launch`, { [eventPrefix.replace('_', '')]: module.title });
    }
  };

  // Handle search navigation - automatically open module when navigated from search
  useEffect(() => {
    if (searchNavigation && searchNavigation.toolId) {
      const targetModule = modules.find(m => m.id === searchNavigation.toolId);
      if (targetModule && targetModule.status === 'available') {
        setActiveModule(targetModule);
      }
    }
  }, [searchNavigation, modules]);

  // If a module is active, render it
  if (activeModule) {
    const ModuleComponent = activeModule.component;
    return (
      <div className="space-y-6">
        {/* Back Navigation */}
        <div className="flex items-center space-x-3">
          <button
            onClick={() => {
              setActiveModule(null);
              trackEvent(`${eventPrefix}_back`, { from: activeModule?.title });
            }}
            className="flex items-center space-x-1 px-2 py-1 text-sm bg-gray-100 dark:bg-gray-800 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
          >
            <span>← Back</span>
          </button>
          <div className="flex items-center space-x-2">
            <activeModule.icon className={`w-6 h-6 ${theme.headerIcon}`} />
            <h1 className="text-2xl font-bold">{activeModule.title}</h1>
          </div>
        </div>

        {/* Render the active module */}
        <ModuleComponent />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex items-center space-x-3">
        <IconComponent className={`w-8 h-8 ${theme.headerIcon}`} />
        <h1 className="text-3xl font-bold">{title}</h1>
      </div>

      {/* Available Modules */}
      <div className="content-area">
        <h2 className="text-xl font-semibold mb-4">Available {title.split(' ')[0]}</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {modules.map((module) => {
            const ModuleIconComponent = module.icon;
            return (
              <div
                key={module.id}
                className={`border ${theme.border} ${theme.glow} rounded-lg p-4 hover:shadow-md cursor-pointer transition-all duration-300 flex flex-col h-full`}
                onClick={() => openModule(module.id)}
              >
                <div className="flex items-center space-x-3 mb-3">
                  <div className={`p-2 ${theme.iconBg} rounded-lg`}>
                    <ModuleIconComponent className={`w-5 h-5 ${theme.iconText}`} />
                  </div>
                  <div>
                    <h4 className="font-semibold">{module.title}</h4>
                    <span className={`text-xs ${theme.badgeBg} ${theme.badgeText} px-2 py-1 rounded`}>
                      {module.status || 'available'}
                    </span>
                  </div>
                </div>
                <p className="text-sm text-gray-600 dark:text-gray-400 mb-3 flex-1">{module.description}</p>
                <button
                  className={`w-full py-2 px-4 ${theme.button} text-white rounded-lg transition-colors mt-auto`}
                  onClick={(e) => {
                    e.stopPropagation();
                    openModule(module.id);
                    trackEvent(`${eventPrefix}_button`, { [eventPrefix.replace('_', '')]: module.title });
                  }}
                >
                  {buttonText}
                </button>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default ModulePage;
