/**
 * DartGame.jsx
 * 301 Dart Game - Full dart throwing game with accuracy mechanics and multiple game modes
 */

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { trackEvent } from '../utils/analytics';

const DartGame = () => {
  const canvasRef = useRef(null);
  const gameStateRef = useRef(null);
  const animationRef = useRef(null);
  const [gameStarted, setGameStarted] = useState(false);

  // Constants
  const WINDOW_WIDTH = 1000; // Changed from 800 to match original
  const WINDOW_HEIGHT = 1000; // Changed from 800 to match original
  const BOARD_RADIUS = Math.floor(WINDOW_WIDTH * 0.25);
  const POINT_CIRCLE = [20, 1, 18, 4, 13, 6, 10, 15, 2, 17, 3, 19, 7, 16, 8, 11, 14, 9, 12, 5];
  const WHITE = '#fff';
  const BLACK = '#000';
  const RED = 'rgb(150,0,0)';
  const GREEN = 'rgb(0,120,0)';
  const BLUE = 'rgb(0,0,150)';
  const YELLOW = 'rgb(255,255,0)';
  const GRAY = 'rgb(128,128,128)';
  const BACKGROUND_COLOR = '#1e1e1e';

  // Game State Class
  class GameState {
    constructor() {
      this.player1_score = 301;
      this.player2_score = 301;
      this.current_player = 1;
      this.darts_thrown = 0;
      this.dart_positions = [];
      this.dart_scores = [];
      this.turn_total = 0;
      this.game_over = false;
      this.winner = null;
      this.show_darts_delay = 0;
      this.bust = false;
      this.last_throw_scores = [];
      this.accuracy_freeze = false;
      this.freeze_timer = 0;
      this.frozen_accuracy = 0;
      this.frozen_bar_pos = 0;
      this.lighting_effect = false;
      this.lighting_timer = 0.0;
      this.lighting_color_phase = 0.0;
    }
  }

  // Dart Animation Class
  class DartAnimation {
    constructor(start_pos, end_pos, angle, start_time, duration = 0.25) {
      this.start_pos = start_pos;
      this.end_pos = end_pos;
      this.angle = angle;
      this.start_time = start_time;
      this.duration = duration;
      this.active = true;
    }

    get_scale(now) {
      let t = (now - this.start_time) / this.duration;
      if (t >= 1.0) {
        this.active = false;
        return 1.0;
      }
      return 5.0 - 4.0 * t;
    }

    get_pos(now) {
      let t = (now - this.start_time) / this.duration;
      if (t >= 1.0) return this.end_pos;
      let x = this.start_pos[0] + (this.end_pos[0] - this.start_pos[0]) * t;
      let y = this.start_pos[1] + (this.end_pos[1] - this.start_pos[1]) * t;
      return [x, y];
    }
  }

  // Game variables
  const gameVarsRef = useRef({
    oscillate_speed: 5.0, // Increased from 1.5 to make it faster like the original difficulties
    oscillator_time: 0,
    space_held: false,
    prev_sin_pos: 0,
    settling: false,
    settle_direction: 0,
    settle_progress: 0,
    settle_duration: 0.5,
    active_dart_animations: [],
    menu_active: true,
    selected_game_type: 301,
    menu_options: [301, 501, 701],
    menu_selected_index: 0,
    player_select_active: false,
    player_options: ["1 Player", "2 Players"],
    player_selected_index: 0,
    single_player_mode: true, // Changed back to true for AI by default
    difficulty_select_active: false,
    difficulty_options: ["Easy", "Medium", "Hard"],
    difficulty_selected_index: 1, // Default to Medium
    ai_thinking_delay: 0,
    ai_accuracy: 0.6 // AI accuracy based on difficulty
  });

  const font = (size, bold = false) => {
    return `${bold ? 'bold ' : ''}${size}px Arial, sans-serif`;
  };

  const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
  const now = () => performance.now() / 1000;

  // Drawing functions
  const drawNumbers = (ctx, number_list, fontSize, center, board_radius) => {
    let count = number_list.length;
    let magnitude = board_radius - board_radius * 0.1;
    let [cx, cy] = center;
    ctx.save();
    ctx.font = font(fontSize, true);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = WHITE;
    for (let i = 0; i < count; ++i) {
      let angle_deg = (360 / count) * i - 90;
      let angle_rad = angle_deg * Math.PI / 180;
      let x = cx + magnitude * Math.cos(angle_rad);
      let y = cy + magnitude * Math.sin(angle_rad);
      ctx.fillText(number_list[i], x, y);
    }
    ctx.restore();
  };

  const drawSegment = (ctx, center, inner_radius, outer_radius, start_angle, end_angle, color) => {
    let [cx, cy] = center;
    ctx.save();
    ctx.beginPath();
    let num_points = 50;
    for (let i = 0; i <= num_points; ++i) {
      let angle = start_angle + (end_angle - start_angle) * i / num_points;
      let x = cx + outer_radius * Math.cos(angle);
      let y = cy + outer_radius * Math.sin(angle);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    for (let i = num_points; i >= 0; --i) {
      let angle = start_angle + (end_angle - start_angle) * i / num_points;
      let x = cx + inner_radius * Math.cos(angle);
      let y = cy + inner_radius * Math.sin(angle);
      ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  };

  const getDartScore = (pos, center, radius) => {
    let [cx, cy] = center, [mx, my] = pos;
    let distance = Math.sqrt((mx - cx) ** 2 + (my - cy) ** 2);
    if (distance > radius) return 0;

    let border_width = Math.floor(radius * 0.012);
    let outer_bullseye_radius = radius - border_width - radius * 0.9;
    let inner_bullseye_radius = outer_bullseye_radius * 0.5;
    let triple_ring_outer = radius - border_width - radius * 0.5 - border_width;
    let triple_ring_inner = radius - border_width - radius * 0.55;
    let double_ring_outer = radius - border_width - radius * 0.2 - border_width;
    let double_ring_inner = radius - border_width - radius * 0.25;

    if (distance <= inner_bullseye_radius) return 50;
    else if (distance <= outer_bullseye_radius) return 25;

    let angle = Math.atan2(my - cy, mx - cx);
    let segment_angle = 2 * Math.PI / 20;
    let separator_angle = 1.5 * Math.PI / 180;
    let offset_angle = segment_angle / 2;
    angle = angle + Math.PI / 2;
    angle = angle - separator_angle / 2;
    angle = angle - offset_angle;
    if (angle < 0) angle += 2 * Math.PI;
    angle = angle % (2 * Math.PI);
    let scoring_ring_segment_index = Math.floor(angle / segment_angle + 1) % 20;
    let point_value = POINT_CIRCLE[scoring_ring_segment_index];

    if (triple_ring_inner <= distance && distance <= triple_ring_outer) return point_value * 3;
    else if (double_ring_inner <= distance && distance <= double_ring_outer) return point_value * 2;
    else return point_value;
  };

  const drawBoard = (ctx, center, radius) => {
    let border_width = Math.floor(radius * 0.012);
    let c1 = 'rgb(100,100,100)', c2 = 'rgb(200,200,200)';

    ctx.save();
    // Outer circle
    ctx.beginPath();
    ctx.arc(center[0], center[1], radius, 0, 2 * Math.PI);
    ctx.fillStyle = WHITE;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(center[0], center[1], radius - border_width, 0, 2 * Math.PI);
    ctx.fillStyle = BLACK;
    ctx.fill();

    drawNumbers(ctx, POINT_CIRCLE, Math.floor(BOARD_RADIUS * 0.1), center, radius);

    // Rings
    let rings = [0.2, 0.25, 0.5, 0.55];
    for (let r of rings) {
      ctx.beginPath();
      ctx.arc(center[0], center[1], radius - border_width - Math.floor(radius * r), 0, 2 * Math.PI);
      ctx.fillStyle = WHITE;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(center[0], center[1], radius - border_width - Math.floor(radius * r) - border_width, 0, 2 * Math.PI);
      ctx.fillStyle = BLACK;
      ctx.fill();
    }

    // Bullseyes
    let outer_bullseye_radius = radius - border_width - Math.floor(radius * 0.9);
    let inner_bullseye_radius = Math.floor(outer_bullseye_radius * 0.5);
    ctx.beginPath();
    ctx.arc(center[0], center[1], outer_bullseye_radius, 0, 2 * Math.PI);
    ctx.fillStyle = BLACK;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(center[0], center[1], outer_bullseye_radius - border_width, 0, 2 * Math.PI);
    ctx.fillStyle = RED;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(center[0], center[1], inner_bullseye_radius, 0, 2 * Math.PI);
    ctx.fillStyle = BLACK;
    ctx.fill();

    // Segments
    let segment_angle = 2 * Math.PI / 20;
    let separator_angle = 1.5 * Math.PI / 180;
    for (let i = 0; i < 20; ++i) {
      let start_angle = i * segment_angle - Math.PI / 2 + separator_angle / 2;
      let end_angle = (i + 1) * segment_angle - Math.PI / 2 - separator_angle / 2;
      let color_12 = (i % 2 === 0) ? c1 : c2;
      let color_23 = (i % 2 === 0) ? RED : GREEN;
      let offset_angle = segment_angle / 2;

      // Draw segments
      let outer_ring_outer = radius - border_width - Math.floor(radius * 0.2) - border_width;
      let outer_ring_inner = radius - border_width - Math.floor(radius * 0.25);
      drawSegment(ctx, center, outer_ring_inner, outer_ring_outer, start_angle + offset_angle, end_angle + offset_angle, color_23);

      let inner_ring_outer = radius - border_width - Math.floor(radius * 0.5) - border_width;
      let inner_ring_inner = radius - border_width - Math.floor(radius * 0.55);
      drawSegment(ctx, center, inner_ring_inner, inner_ring_outer, start_angle + offset_angle, end_angle + offset_angle, color_23);

      let single_area_outer = radius - border_width - Math.floor(radius * 0.55) - border_width;
      let single_area_inner = outer_bullseye_radius;
      drawSegment(ctx, center, single_area_inner, single_area_outer, start_angle + offset_angle, end_angle + offset_angle, color_12);

      let between_rings_outer = radius - border_width - Math.floor(radius * 0.25) - border_width;
      let between_rings_inner = radius - border_width - Math.floor(radius * 0.5);
      drawSegment(ctx, center, between_rings_inner, between_rings_outer, start_angle + offset_angle, end_angle + offset_angle, color_12);
    }

    // Segment lines
    for (let i = 0; i < 20; ++i) {
      let angle = (i + 0.5) * segment_angle - Math.PI / 2;
      let start_radius = outer_bullseye_radius;
      let end_radius = radius - border_width;
      let start_x = center[0] + start_radius * Math.cos(angle);
      let start_y = center[1] + start_radius * Math.sin(angle);
      let end_x = center[0] + end_radius * Math.cos(angle);
      let end_y = center[1] + end_radius * Math.sin(angle);
      ctx.beginPath();
      ctx.moveTo(start_x, start_y);
      ctx.lineTo(end_x, end_y);
      ctx.strokeStyle = WHITE;
      ctx.lineWidth = 2;
      ctx.stroke();
    }
    ctx.restore();
  };

  const drawThrowMeter = (ctx, bar_pos) => {
    let border_width = 3;
    let outer_x = (WINDOW_WIDTH / 2) - Math.floor(WINDOW_WIDTH * 0.1);
    let outer_y = WINDOW_HEIGHT - Math.floor(WINDOW_HEIGHT * 0.09);
    let outer_w = Math.floor(WINDOW_WIDTH * 0.2);
    let outer_h = Math.floor(WINDOW_HEIGHT * 0.03);

    ctx.save();
    ctx.strokeStyle = WHITE;
    ctx.lineWidth = border_width;
    ctx.strokeRect(outer_x, outer_y, outer_w, outer_h);

    let inner_x = outer_x + border_width;
    let inner_y = outer_y + border_width;
    let inner_w = outer_w - 2 * border_width;
    let inner_h = outer_h - 2 * border_width;
    let half_w = Math.floor(inner_w / 2);

    // Color gradient
    for (let i = 0; i < inner_w; ++i) {
      let r, g, b;
      if (i < half_w) {
        let ratio = i / half_w;
        if (ratio < 0.5) {
          let sub_ratio = ratio / 0.5;
          r = 255;
          g = Math.floor(255 * sub_ratio);
          b = 0;
        } else {
          let sub_ratio = (ratio - 0.5) / 0.5;
          r = Math.floor(255 * (1 - sub_ratio));
          g = 255;
          b = 0;
        }
      } else {
        let ratio = (i - half_w) / half_w;
        if (ratio < 0.5) {
          let sub_ratio = ratio / 0.5;
          r = Math.floor(255 * sub_ratio);
          g = 255;
          b = 0;
        } else {
          let sub_ratio = (ratio - 0.5) / 0.5;
          r = 255;
          g = Math.floor(255 * (1 - sub_ratio));
          b = 0;
        }
      }
      ctx.beginPath();
      ctx.strokeStyle = `rgb(${r},${g},${b})`;
      ctx.moveTo(inner_x + i, inner_y);
      ctx.lineTo(inner_x + i, inner_y + inner_h);
      ctx.stroke();
    }

    // Center indicator
    let center_x = inner_x + Math.floor(inner_w / 2);
    ctx.beginPath();
    ctx.strokeStyle = WHITE;
    ctx.lineWidth = 2;
    ctx.moveTo(center_x, inner_y - 5);
    ctx.lineTo(center_x, inner_y + inner_h + 5);
    ctx.stroke();

    // Bar
    let bar_x = inner_x + Math.floor(bar_pos * (inner_w - 3)) + 1;
    ctx.beginPath();
    ctx.strokeStyle = gameStateRef.current?.accuracy_freeze ? YELLOW : BLACK;
    ctx.lineWidth = 3;
    ctx.moveTo(bar_x, inner_y);
    ctx.lineTo(bar_x, inner_y + inner_h);
    ctx.stroke();
    ctx.restore();
  };

  const drawDart = (ctx, pos, angle_offset = 0) => {
    let [x, y] = pos;
    let dart_size = Math.floor(BOARD_RADIUS * 0.08);
    let angles = [angle_offset, angle_offset + 2 * Math.PI / 3, angle_offset + 4 * Math.PI / 3];
    ctx.save();
    ctx.strokeStyle = YELLOW;
    ctx.lineWidth = 3;
    for (let angle of angles) {
      let end_x = x + dart_size * Math.cos(angle);
      let end_y = y + dart_size * Math.sin(angle);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(end_x, end_y);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.arc(x, y, 3, 0, 2 * Math.PI);
    ctx.fillStyle = RED;
    ctx.fill();
    ctx.restore();
  };

  const drawDartScaled = (ctx, pos, angle_offset = 0, scale = 1.0) => {
    let [x, y] = pos;
    let dart_size = Math.floor(BOARD_RADIUS * 0.08 * scale);
    let angles = [angle_offset, angle_offset + 2 * Math.PI / 3, angle_offset + 4 * Math.PI / 3];
    ctx.save();
    ctx.strokeStyle = YELLOW;
    ctx.lineWidth = Math.max(1, Math.floor(3 * scale));
    for (let angle of angles) {
      let end_x = x + dart_size * Math.cos(angle);
      let end_y = y + dart_size * Math.sin(angle);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(end_x, end_y);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.arc(x, y, Math.max(2, Math.floor(3 * scale)), 0, 2 * Math.PI);
    ctx.fillStyle = RED;
    ctx.fill();
    ctx.restore();
  };

  const applyAccuracyVariance = (target_pos, center, accuracy) => {
    let variance = (1 - accuracy) * BOARD_RADIUS * 0.6;
    let angle_offset = Math.random() * 2 * Math.PI - Math.PI;
    let magnitude_offset = Math.random() * variance;
    let offset_x = magnitude_offset * Math.cos(angle_offset);
    let offset_y = magnitude_offset * Math.sin(angle_offset);
    return [target_pos[0] + offset_x, target_pos[1] + offset_y];
  };

  const isValidFinish = (remaining_score, dart_score) => {
    return remaining_score === dart_score && dart_score % 2 === 0 && dart_score <= 40;
  };

  const checkBust = (remaining_score, dart_score) => {
    return remaining_score - dart_score < 0 || remaining_score - dart_score === 1;
  };

  const nextTurn = () => {
    const gameState = gameStateRef.current;
    gameState.current_player = (gameState.current_player === 1) ? 2 : 1;
    gameState.darts_thrown = 0;
    gameState.dart_positions = [];
    gameState.dart_scores = [];
    gameState.turn_total = 0;
    gameState.bust = false;
    gameState.last_throw_scores = [];
  };

  const throwDart = (click_pos, accuracy, bar_pos) => {
    const gameState = gameStateRef.current;
    const gameVars = gameVarsRef.current;

    if (gameState.game_over || gameState.darts_thrown >= 3 || gameState.accuracy_freeze) return;

    let board_center = [WINDOW_WIDTH / 2, WINDOW_HEIGHT / 2];
    let penalty_factor = 1 + Math.abs(bar_pos - 0.5) * 0.5;
    let actual_accuracy = Math.max(0.1, accuracy / penalty_factor);
    let actual_pos = applyAccuracyVariance(click_pos, board_center, actual_accuracy);
    let dart_score = getDartScore(actual_pos, board_center, BOARD_RADIUS);

    gameState.frozen_accuracy = actual_accuracy;
    gameState.frozen_bar_pos = bar_pos;
    gameState.accuracy_freeze = true;
    gameState.freeze_timer = 1.0;

    let current_score = (gameState.current_player === 1) ? gameState.player1_score : gameState.player2_score;
    let remaining_after_turn = current_score - (gameState.turn_total + dart_score);

    if (checkBust(current_score - gameState.turn_total, dart_score)) {
      gameState.bust = true;
      gameState.dart_positions.push(actual_pos);
      gameState.dart_scores.push(dart_score);
      gameState.last_throw_scores.push(dart_score);
      gameState.darts_thrown = 3;
      gameState.show_darts_delay = 2.0;
      return;
    }

    if (remaining_after_turn === 0) {
      if (isValidFinish(current_score - gameState.turn_total, dart_score)) {
        gameState.dart_positions.push(actual_pos);
        gameState.dart_scores.push(dart_score);
        gameState.last_throw_scores.push(dart_score);
        gameState.turn_total += dart_score;
        if (gameState.current_player === 1) gameState.player1_score = 0;
        else gameState.player2_score = 0;
        gameState.winner = gameState.current_player;
        gameState.game_over = true;
        trackEvent('dart_game_win', { player: gameState.current_player, score: dart_score });
        return;
      } else {
        gameState.bust = true;
        gameState.dart_positions.push(actual_pos);
        gameState.dart_scores.push(dart_score);
        gameState.last_throw_scores.push(dart_score);
        gameState.darts_thrown = 3;
        gameState.show_darts_delay = 2.0;
        return;
      }
    }

    gameState.dart_positions.push(actual_pos);
    gameState.dart_scores.push(dart_score);
    gameState.last_throw_scores.push(dart_score);
    gameState.turn_total += dart_score;
    gameState.darts_thrown += 1;

    let angle = 0;
    let start_pos = [click_pos[0], actual_pos[1]];
    gameVars.active_dart_animations.push(new DartAnimation(start_pos, actual_pos, angle, now()));

    if (gameState.darts_thrown >= 3) gameState.show_darts_delay = 2.0;

    trackEvent('dart_throw', { score: dart_score, player: gameState.current_player });
  };

  // AI Logic
  const aiThrow = () => {
    const gameState = gameStateRef.current;
    const gameVars = gameVarsRef.current;

    if (!gameVars.single_player_mode || gameState.current_player !== 2 || gameState.game_over || gameState.accuracy_freeze || gameState.darts_thrown >= 3) return;

    let board_center = [WINDOW_WIDTH / 2, WINDOW_HEIGHT / 2];
    let remaining = gameState.player2_score - gameState.turn_total;
    let double_targets = Array.from({length: 20}, (_, n) => 2 * (n + 1)).concat([50]);
    let finish_score = null;
    for (let d of double_targets) if (remaining === d) { finish_score = d; break; }
    let target_pos, accuracy;

    // Make AI less accurate and more random like the original
    if (finish_score) {
      if (finish_score === 50) {
        // Bullseye: add more random offset
        let angle = Math.random() * 2 * Math.PI;
        let r = Math.random() * BOARD_RADIUS * 0.25;
        target_pos = [board_center[0] + r * Math.cos(angle), board_center[1] + r * Math.sin(angle)];
      } else {
        let idx = double_targets.indexOf(finish_score);
        let segment = idx < 20 ? idx : 0;
        let angle = (2 * Math.PI / 20) * segment - Math.PI / 2;
        // Add more random angle and radius offset
        angle += (Math.random() * 0.6 - 0.3); // wider spread
        let r = BOARD_RADIUS - Math.floor(BOARD_RADIUS * 0.225);
        r += (Math.random() * 2 * BOARD_RADIUS * 0.12 - BOARD_RADIUS * 0.12); // more random radius
        target_pos = [board_center[0] + r * Math.cos(angle), board_center[1] + r * Math.sin(angle)];
      }
      accuracy = Math.random() * 0.35 + 0.45; // lower accuracy
    } else {
      if (remaining > 60) {
        let angle = (2 * Math.PI / 20) * 0 - Math.PI / 2;
        angle += (Math.random() * 0.7 - 0.35); // much wider spread
        let r = BOARD_RADIUS - Math.floor(BOARD_RADIUS * 0.525);
        r += (Math.random() * 2 * BOARD_RADIUS * 0.15 - BOARD_RADIUS * 0.15); // more random radius
        target_pos = [board_center[0] + r * Math.cos(angle), board_center[1] + r * Math.sin(angle)];
        accuracy = Math.random() * 0.45 + 0.15; // much lower accuracy
      } else {
        let best = null;
        for (let d of double_targets) if (POINT_CIRCLE.includes(remaining - d)) { best = remaining - d; break; }
        if (best !== null) {
          let idx = POINT_CIRCLE.indexOf(best);
          let angle = (2 * Math.PI / 20) * idx - Math.PI / 2;
          angle += (Math.random() * 0.6 - 0.3); // wider spread
          let r = BOARD_RADIUS * 0.7;
          r += (Math.random() * 2 * BOARD_RADIUS * 0.12 - BOARD_RADIUS * 0.12);
          target_pos = [board_center[0] + r * Math.cos(angle), board_center[1] + r * Math.sin(angle)];
          accuracy = Math.random() * 0.35 + 0.25;
        } else {
          let angle = Math.random() * 2 * Math.PI;
          let r = BOARD_RADIUS * (0.3 + Math.random() * 0.7);
          target_pos = [board_center[0] + r * Math.cos(angle), board_center[1] + r * Math.sin(angle)];
          accuracy = Math.random() * 0.4 + 0.1;
        }
      }
    }

    let bar_pos = Math.random();
    throwDart(target_pos, accuracy, bar_pos);
  };

  const drawScores = (ctx) => {
    const gameState = gameStateRef.current;
    const gameVars = gameVarsRef.current;
    let live_p1, live_p2;
    if (gameState.current_player === 1) {
      live_p1 = gameState.bust ? gameState.player1_score : gameState.player1_score - gameState.turn_total;
      live_p2 = gameState.player2_score;
    } else {
      live_p1 = gameState.player1_score;
      live_p2 = gameState.bust ? gameState.player2_score : gameState.player2_score - gameState.turn_total;
    }

    ctx.save();
    ctx.font = font(Math.floor(WINDOW_WIDTH * 0.035), true); // Slightly smaller font
    ctx.fillStyle = WHITE;
    ctx.textAlign = 'left';
    ctx.fillText(`You: ${live_p1}`, Math.floor(WINDOW_WIDTH * 0.05), Math.floor(WINDOW_HEIGHT * 0.05));
    ctx.textAlign = 'right';
    const aiLabel = gameVars.single_player_mode ? `AI (${gameVars.difficulty_options[gameVars.difficulty_selected_index]}): ${live_p2}` : `Player 2: ${live_p2}`;
    ctx.fillText(aiLabel, Math.floor(WINDOW_WIDTH * 0.95), Math.floor(WINDOW_HEIGHT * 0.05));
    ctx.textAlign = 'center';
    ctx.font = font(Math.floor(WINDOW_WIDTH * 0.025), true);
    ctx.fillStyle = YELLOW;
    const turnLabel = gameState.current_player === 1 ? "Your Turn" : (gameVars.single_player_mode ? "AI's Turn" : "Player 2's Turn");
    ctx.fillText(turnLabel, WINDOW_WIDTH / 2, Math.floor(WINDOW_HEIGHT * 0.08));
    ctx.fillStyle = WHITE;
    ctx.fillText(`Darts: ${gameState.darts_thrown}/3`, WINDOW_WIDTH / 2, Math.floor(WINDOW_HEIGHT * 0.11));
    if (gameState.turn_total > 0) {
      ctx.fillText(`Turn Total: ${gameState.turn_total}`, WINDOW_WIDTH / 2, Math.floor(WINDOW_HEIGHT * 0.14));
    }
    ctx.restore();
  };

  const drawInstructions = (ctx) => {
    ctx.save();
    ctx.font = font(Math.floor(WINDOW_WIDTH * 0.025), true);
    ctx.fillStyle = WHITE;
    ctx.textAlign = 'center';
    ctx.fillText('Hold SPACE and click on dartboard to throw', WINDOW_WIDTH / 2, Math.floor(WINDOW_HEIGHT * 0.18));
    ctx.restore();
  };

  const drawGameOver = (ctx) => {
    const gameState = gameStateRef.current;
    if (gameState.game_over) {
      ctx.save();
      ctx.font = font(Math.floor(WINDOW_WIDTH * 0.04), true);
      ctx.fillStyle = YELLOW;
      ctx.textAlign = 'center';
      ctx.fillText(`Player ${gameState.winner} Wins!`, WINDOW_WIDTH / 2, WINDOW_HEIGHT / 2);
      ctx.font = font(Math.floor(WINDOW_WIDTH * 0.025), true);
      ctx.fillStyle = WHITE;
      ctx.fillText('Press R to restart', WINDOW_WIDTH / 2, WINDOW_HEIGHT / 2 + Math.floor(WINDOW_HEIGHT * 0.05));
      ctx.restore();
    }
  };

  const drawBustMessage = (ctx) => {
    const gameState = gameStateRef.current;
    if (gameState.bust) {
      ctx.save();
      ctx.font = font(Math.floor(WINDOW_WIDTH * 0.04), true);
      ctx.fillStyle = RED;
      ctx.textAlign = 'center';
      ctx.fillText('BUST!', WINDOW_WIDTH / 2, Math.floor(WINDOW_HEIGHT * 0.35));
      ctx.restore();
    }
  };

  const restartGame = () => {
    gameStateRef.current = new GameState();
    gameStateRef.current.player1_score = gameVarsRef.current.selected_game_type;
    gameStateRef.current.player2_score = gameVarsRef.current.selected_game_type;
    gameVarsRef.current.active_dart_animations = [];
    gameVarsRef.current.menu_active = false;
    // Keep gameStarted as true since we're just restarting
    trackEvent('dart_game_restart');
  };

  const startGame = () => {
    gameStateRef.current = new GameState();
    gameStateRef.current.player1_score = gameVarsRef.current.selected_game_type;
    gameStateRef.current.player2_score = gameVarsRef.current.selected_game_type;
    gameVarsRef.current.menu_active = false;
    gameVarsRef.current.active_dart_animations = [];
    setGameStarted(true);
    trackEvent('dart_game_start', { game_type: gameVarsRef.current.selected_game_type });
  };

  const getMousePos = useCallback((e) => {
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return [
      (e.clientX - rect.left) * scaleX,
      (e.clientY - rect.top) * scaleY
    ];
  }, []);

  // Game loop
  const gameLoop = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const gameState = gameStateRef.current;
    const gameVars = gameVarsRef.current;

    if (!gameState) return;

    const now_time = now();
    const delta = 1/60; // Assuming 60 FPS

    // Clear canvas
    ctx.fillStyle = BACKGROUND_COLOR;
    ctx.fillRect(0, 0, WINDOW_WIDTH, WINDOW_HEIGHT);

    if (gameVars.menu_active) {
      // Draw menu
      ctx.save();
      ctx.font = font(Math.floor(WINDOW_WIDTH * 0.08), true);
      ctx.fillStyle = WHITE;
      ctx.textAlign = 'center';
      ctx.fillText('301 Darts Game', WINDOW_WIDTH / 2, Math.floor(WINDOW_HEIGHT * 0.3));
      ctx.font = font(Math.floor(WINDOW_WIDTH * 0.03), true);
      ctx.fillStyle = GRAY;
      ctx.fillText('Click "Start Game" to begin', WINDOW_WIDTH / 2, Math.floor(WINDOW_HEIGHT * 0.6));
      ctx.restore();
      return;
    }

    // Update timers
    if (gameState.accuracy_freeze) {
      gameState.freeze_timer -= delta;
      if (gameState.freeze_timer <= 0) {
        gameState.accuracy_freeze = false;
      }
    }

    if (gameState.show_darts_delay > 0) {
      gameState.show_darts_delay -= delta;
      if (gameState.show_darts_delay <= 0) {
        if (gameState.current_player === 1) {
          gameState.player1_score -= gameState.turn_total;
        } else {
          gameState.player2_score -= gameState.turn_total;
        }
        nextTurn();
      }
    }

    // Update oscillator
    if (!gameVars.settling) {
      gameVars.oscillator_time += delta * gameVars.oscillate_speed;
    } else {
      gameVars.settle_progress += delta / gameVars.settle_duration;
      if (gameVars.settle_progress >= 1) {
        gameVars.settling = false;
        gameVars.settle_progress = 0;
      }
    }

    // CRITICAL: AI turn triggering logic from original game
    if (gameVars.single_player_mode && !gameState.game_over && gameState.current_player === 2 &&
        !gameState.accuracy_freeze && gameState.darts_thrown < 3 && gameState.show_darts_delay <= 0) {
      aiThrow();
    }

    // Draw game
    drawBoard(ctx, [WINDOW_WIDTH / 2, WINDOW_HEIGHT / 2], BOARD_RADIUS);

    // Draw darts
    for (let i = 0; i < gameState.dart_positions.length; ++i) {
      drawDart(ctx, gameState.dart_positions[i], 0);
    }

    // Draw dart animations
    for (let anim of gameVars.active_dart_animations) {
      if (anim.active) {
        let scale = anim.get_scale(now_time);
        let pos = anim.get_pos(now_time);
        drawDartScaled(ctx, pos, anim.angle, scale);
      }
    }
    gameVars.active_dart_animations = gameVars.active_dart_animations.filter(a => a.active);

    // Draw throw meter
    let bar_pos;
    if (gameState.accuracy_freeze) bar_pos = gameState.frozen_bar_pos;
    else if (gameVars.space_held) bar_pos = (Math.sin(gameVars.oscillator_time) + 1) / 2;
    else if (gameVars.settling) {
      let start = (Math.sin(gameVars.oscillator_time) + 1) / 2;
      let end = gameVars.settle_direction > 0 ? 1.0 : 0.0;
      bar_pos = start + (end - start) * gameVars.settle_progress;
    } else bar_pos = gameVars.settle_direction > 0 ? 1.0 : 0.0;

    drawThrowMeter(ctx, bar_pos);
    drawScores(ctx);
    drawInstructions(ctx);
    drawBustMessage(ctx);
    drawGameOver(ctx);

    if (gameState.last_throw_scores.length > 0) {
      ctx.save();
      ctx.font = font(Math.floor(WINDOW_WIDTH * 0.025), true);
      ctx.fillStyle = WHITE;
      ctx.textAlign = 'center';
      let scores_text = `Last throw: ${gameState.last_throw_scores.join(' + ')} = ${gameState.last_throw_scores.reduce((a,b)=>a+b,0)}`;
      ctx.fillText(scores_text, WINDOW_WIDTH / 2, Math.floor(WINDOW_HEIGHT * 0.88));
      ctx.restore();
    }

    animationRef.current = requestAnimationFrame(gameLoop);
  }, []);

  // Event handlers
  const handleKeyDown = useCallback((e) => {
    const gameVars = gameVarsRef.current;
    const gameState = gameStateRef.current;

    if (e.code === 'Space') {
      e.preventDefault();
      if (!gameVars.menu_active && !gameState?.game_over) {
        gameVars.space_held = true;
      }
    }

    if (e.code === 'KeyR') {
      if (gameState?.game_over) {
        restartGame();
      }
    }
  }, []);

  const handleKeyUp = useCallback((e) => {
    const gameVars = gameVarsRef.current;

    if (e.code === 'Space') {
      e.preventDefault();
      if (!gameVars.menu_active) {
        gameVars.space_held = false;
        gameVars.settling = true;
        gameVars.settle_direction = Math.random() > 0.5 ? 1 : -1;
        gameVars.settle_progress = 0;
      }
    }
  }, []);

  const handleClick = useCallback((e) => {
    const gameVars = gameVarsRef.current;
    const gameState = gameStateRef.current;

    if (gameVars.menu_active || !gameState) return;

    const mousePos = getMousePos(e);
    let accuracy = 0.7; // Medium difficulty
    let bar_pos = gameState.accuracy_freeze ? gameState.frozen_bar_pos :
                  (gameVars.space_held ? (Math.sin(gameVars.oscillator_time) + 1) / 2 :
                   (gameVars.settle_direction > 0 ? 1.0 : 0.0));

    throwDart(mousePos, accuracy, bar_pos);
  }, [getMousePos]);

  // Initialize game
  useEffect(() => {
    gameStateRef.current = new GameState();
    gameVarsRef.current.menu_active = !gameStarted;

    // Add event listeners
    document.addEventListener('keydown', handleKeyDown);
    document.addEventListener('keyup', handleKeyUp);

    // Start game loop
    gameLoop();

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.removeEventListener('keyup', handleKeyUp);
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [handleKeyDown, handleKeyUp, gameLoop, gameStarted]);

  const handleStartGame = () => {
    gameStateRef.current = new GameState();
    gameStateRef.current.player1_score = gameVarsRef.current.selected_game_type;
    gameStateRef.current.player2_score = gameVarsRef.current.selected_game_type;
    gameVarsRef.current.menu_active = false;
    gameVarsRef.current.active_dart_animations = [];
    setGameStarted(true);
    trackEvent('dart_game_start', { game_type: gameVarsRef.current.selected_game_type });
  };

  const handleRestartGame = () => {
    gameStateRef.current = new GameState();
    gameStateRef.current.player1_score = gameVarsRef.current.selected_game_type;
    gameStateRef.current.player2_score = gameVarsRef.current.selected_game_type;
    gameVarsRef.current.active_dart_animations = [];
    gameVarsRef.current.menu_active = false;
    // Keep gameStarted as true since we're just restarting
    trackEvent('dart_game_restart');
  };

  return (
    <div className="flex flex-col items-center space-y-4">
      <div className="text-center">
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">301 Darts Game</h2>
        <p className="text-gray-600 dark:text-gray-400">
          Reduce your score to exactly zero using doubles to finish
        </p>
      </div>

      {!gameStarted && (
        <div className="space-y-4 text-center">
          <button
            onClick={startGame}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            Start Game
          </button>
          <div className="text-sm text-gray-600 dark:text-gray-400">
            <p>• Hold SPACE and click on dartboard to throw</p>
            <p>• Aim for the center of the accuracy meter for best results</p>
            <p>• Finish with a double to win!</p>
          </div>
        </div>
      )}

      <div className="border-2 border-gray-300 dark:border-gray-600 rounded-lg overflow-hidden">
        <canvas
          ref={canvasRef}
          width={WINDOW_WIDTH}
          height={WINDOW_HEIGHT}
          onClick={handleClick}
          className="block bg-gray-900 cursor-crosshair"
          style={{ maxWidth: '100%', height: 'auto' }}
        />
      </div>

      {gameStarted && (
        <div className="text-center space-y-2">
          <button
            onClick={restartGame}
            className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
          >
            Restart Game
          </button>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            Press R during game over to restart
          </p>
        </div>
      )}
    </div>
  );
};

export default DartGame;
