/**
 * PomodoroTimer.jsx
 * Full-featured Pomodoro productivity timer with sessions, stats, and customization
 */

import React, { useState, useEffect, useRef } from 'react';
import { Play, Pause, Square, RotateCcw, Settings, BarChart3, Coffee, Brain, Target, FileSpreadsheet } from 'lucide-react';
import { trackEvent } from '../utils/analytics';
import * as XLSX from 'xlsx';

const PomodoroTimer = () => {
  // Core timer state
  const [timeLeft, setTimeLeft] = useState(25 * 60); // 25 minutes in seconds
  const [isRunning, setIsRunning] = useState(false);
  const [currentMode, setCurrentMode] = useState('work'); // 'work', 'shortBreak', 'longBreak'
  const [completedPomodoros, setCompletedPomodoros] = useState(0);
  const [currentCycle, setCurrentCycle] = useState(1);

  // Settings state
  const [showSettings, setShowSettings] = useState(false);
  const [settings, setSettings] = useState({
    workDuration: 25,
    shortBreakDuration: 5,
    longBreakDuration: 15,
    pomodorosUntilLongBreak: 4,
    autoStartBreaks: false,
    autoStartWork: false,
    notifications: true,
    sounds: true
  });

  // Statistics state
  const [showStats, setShowStats] = useState(false);
  const [todayStats, setTodayStats] = useState({
    completedPomodoros: 0,
    totalFocusTime: 0, // in minutes
    totalBreakTime: 0,
    startTime: null,
    sessions: []
  });

  // Task management state
  const [tasks, setTasks] = useState([]);
  const [currentTask, setCurrentTask] = useState('');
  const [newTask, setNewTask] = useState('');

  // Refs
  const intervalRef = useRef(null);
  const audioRef = useRef(null);

  // Mode configurations
  const modeConfig = {
    work: {
      duration: settings.workDuration * 60,
      label: 'Work Session',
      color: 'bg-red-500',
      lightColor: 'bg-red-100',
      textColor: 'text-red-800',
      icon: Brain,
      message: 'Time to focus!'
    },
    shortBreak: {
      duration: settings.shortBreakDuration * 60,
      label: 'Short Break',
      color: 'bg-green-500',
      lightColor: 'bg-green-100',
      textColor: 'text-green-800',
      icon: Coffee,
      message: 'Take a quick break!'
    },
    longBreak: {
      duration: settings.longBreakDuration * 60,
      label: 'Long Break',
      color: 'bg-blue-500',
      lightColor: 'bg-blue-100',
      textColor: 'text-blue-800',
      icon: Target,
      message: 'Enjoy your long break!'
    }
  };

  // Initialize timer with current mode duration
  useEffect(() => {
    setTimeLeft(modeConfig[currentMode].duration);
  }, [currentMode, settings]);

  // Main timer effect
  useEffect(() => {
    if (isRunning && timeLeft > 0) {
      intervalRef.current = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            handleTimerComplete();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      clearInterval(intervalRef.current);
    }

    return () => clearInterval(intervalRef.current);
  }, [isRunning, timeLeft]);

  // Load data from localStorage on mount
  useEffect(() => {
    const savedStats = localStorage.getItem('pomodoro-today-stats');
    const savedTasks = localStorage.getItem('pomodoro-tasks');
    const savedSettings = localStorage.getItem('pomodoro-settings');

    if (savedStats) {
      const stats = JSON.parse(savedStats);
      // Check if it's a new day
      const today = new Date().toDateString();
      const statsDate = stats.startTime ? new Date(stats.startTime).toDateString() : null;

      if (today === statsDate) {
        setTodayStats(stats);
        setCompletedPomodoros(stats.completedPomodoros);
      }
    }

    if (savedTasks) {
      setTasks(JSON.parse(savedTasks));
    }

    if (savedSettings) {
      setSettings(JSON.parse(savedSettings));
    }

    // Set start time if not set
    setTodayStats(prev => ({
      ...prev,
      startTime: prev.startTime || new Date().toISOString()
    }));
  }, []);

  // Save data to localStorage
  useEffect(() => {
    localStorage.setItem('pomodoro-today-stats', JSON.stringify(todayStats));
  }, [todayStats]);

  useEffect(() => {
    localStorage.setItem('pomodoro-tasks', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    localStorage.setItem('pomodoro-settings', JSON.stringify(settings));
  }, [settings]);

  // Handle timer completion
  const handleTimerComplete = () => {
    setIsRunning(false);

    if (settings.sounds) {
      // Simple beep sound using Web Audio API
      const audioContext = new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = audioContext.createOscillator();
      const gainNode = audioContext.createGain();

      oscillator.connect(gainNode);
      gainNode.connect(audioContext.destination);

      oscillator.frequency.setValueAtTime(800, audioContext.currentTime);
      gainNode.gain.setValueAtTime(0.1, audioContext.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.5);

      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.5);
    }

    if (settings.notifications && 'Notification' in window) {
      if (Notification.permission === 'granted') {
        new Notification(`${modeConfig[currentMode].label} Complete!`, {
          body: getNextModeMessage(),
          icon: '/favicon.ico'
        });
      } else if (Notification.permission !== 'denied') {
        Notification.requestPermission();
      }
    }

    // Update statistics
    const sessionDuration = modeConfig[currentMode].duration / 60;
    const newSession = {
      type: currentMode,
      duration: sessionDuration,
      completedAt: new Date().toISOString(),
      task: currentTask
    };

    setTodayStats(prev => ({
      ...prev,
      sessions: [...prev.sessions, newSession],
      ...(currentMode === 'work' ? {
        completedPomodoros: prev.completedPomodoros + 1,
        totalFocusTime: prev.totalFocusTime + sessionDuration
      } : {
        totalBreakTime: prev.totalBreakTime + sessionDuration
      })
    }));

    // Handle mode transitions
    if (currentMode === 'work') {
      const newCompletedCount = completedPomodoros + 1;
      setCompletedPomodoros(newCompletedCount);

      if (newCompletedCount % settings.pomodorosUntilLongBreak === 0) {
        setCurrentMode('longBreak');
        setCurrentCycle(prev => prev + 1);
      } else {
        setCurrentMode('shortBreak');
      }

      if (settings.autoStartBreaks) {
        setTimeout(() => setIsRunning(true), 1000);
      }
    } else {
      setCurrentMode('work');
      if (settings.autoStartWork) {
        setTimeout(() => setIsRunning(true), 1000);
      }
    }

    trackEvent('pomodoro_session_complete', {
      mode: currentMode,
      duration: sessionDuration,
      completedPomodoros: currentMode === 'work' ? completedPomodoros + 1 : completedPomodoros
    });
  };

  const getNextModeMessage = () => {
    if (currentMode === 'work') {
      const nextCount = completedPomodoros + 1;
      if (nextCount % settings.pomodorosUntilLongBreak === 0) {
        return 'Time for a long break!';
      }
      return 'Time for a short break!';
    }
    return 'Ready for another work session?';
  };

  // Timer controls
  const startTimer = () => {
    setIsRunning(true);
    trackEvent('pomodoro_start', { mode: currentMode, timeLeft });
  };

  const pauseTimer = () => {
    setIsRunning(false);
    trackEvent('pomodoro_pause', { mode: currentMode, timeLeft });
  };

  const resetTimer = () => {
    setIsRunning(false);
    setTimeLeft(modeConfig[currentMode].duration);
    trackEvent('pomodoro_reset', { mode: currentMode });
  };

  const skipSession = () => {
    setIsRunning(false);
    handleTimerComplete();
    trackEvent('pomodoro_skip', { mode: currentMode });
  };

  // Task management
  const addTask = () => {
    if (newTask.trim()) {
      const task = {
        id: Date.now(),
        text: newTask.trim(),
        completed: false,
        pomodorosSpent: 0,
        createdAt: new Date().toISOString()
      };
      setTasks(prev => [...prev, task]);
      setNewTask('');
      trackEvent('pomodoro_task_add', { taskCount: tasks.length + 1 });
    }
  };

  const toggleTask = (id) => {
    setTasks(prev => prev.map(task =>
      task.id === id ? { ...task, completed: !task.completed } : task
    ));
  };

  const deleteTask = (id) => {
    setTasks(prev => prev.filter(task => task.id !== id));
    if (currentTask === tasks.find(t => t.id === id)?.text) {
      setCurrentTask('');
    }
  };

  // Utility functions
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getProgress = () => {
    const total = modeConfig[currentMode].duration;
    return ((total - timeLeft) / total) * 100;
  };

  const currentModeConfig = modeConfig[currentMode];
  const IconComponent = currentModeConfig.icon;

  // Export to Excel
  const exportToExcel = () => {
    const worksheet = XLSX.utils.json_to_sheet(todayStats.sessions);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Sessions');

    // Generate buffer
    XLSX.writeFile(workbook, `Pomodoro_Sessions_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <div className="text-center space-y-2">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Pomodoro Timer</h1>
        <p className="text-gray-600 dark:text-gray-400">
          Boost your productivity with focused work sessions
        </p>
      </div>

      {/* Main Timer */}
      <div className={`${currentModeConfig.lightColor} dark:bg-gray-800 rounded-2xl p-8 text-center space-y-6`}>
        {/* Mode Indicator */}
        <div className="flex items-center justify-center space-x-3">
          <div className={`p-3 ${currentModeConfig.color} rounded-xl`}>
            <IconComponent className="w-6 h-6 text-white" />
          </div>
          <div>
            <h2 className={`text-xl font-bold ${currentModeConfig.textColor} dark:text-white`}>
              {currentModeConfig.label}
            </h2>
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Session {completedPomodoros + 1} • Cycle {currentCycle}
            </p>
          </div>
        </div>

        {/* Progress Circle */}
        <div className="relative w-48 h-48 mx-auto">
          <svg className="w-48 h-48 transform -rotate-90" viewBox="0 0 100 100">
            <circle
              cx="50"
              cy="50"
              r="45"
              stroke="currentColor"
              strokeWidth="2"
              fill="transparent"
              className="text-gray-300 dark:text-gray-600"
            />
            <circle
              cx="50"
              cy="50"
              r="45"
              stroke="currentColor"
              strokeWidth="3"
              fill="transparent"
              strokeDasharray={`${2 * Math.PI * 45}`}
              strokeDashoffset={`${2 * Math.PI * 45 * (1 - getProgress() / 100)}`}
              className={currentModeConfig.color.replace('bg-', 'text-')}
              strokeLinecap="round"
            />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="text-center">
              <div className="text-4xl font-mono font-bold text-gray-900 dark:text-white">
                {formatTime(timeLeft)}
              </div>
              <div className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                {Math.round(getProgress())}% complete
              </div>
            </div>
          </div>
        </div>

        {/* Current Task */}
        {currentTask && (
          <div className="bg-white dark:bg-gray-700 rounded-lg p-4">
            <p className="text-sm text-gray-600 dark:text-gray-400">Current Task:</p>
            <p className="font-medium text-gray-900 dark:text-white">{currentTask}</p>
          </div>
        )}

        {/* Timer Controls */}
        <div className="flex items-center justify-center space-x-4">
          {!isRunning ? (
            <button
              onClick={startTimer}
              className={`flex items-center space-x-2 px-6 py-3 ${currentModeConfig.color} text-white rounded-lg hover:opacity-90 transition-opacity`}
            >
              <Play className="w-5 h-5" />
              <span>Start</span>
            </button>
          ) : (
            <button
              onClick={pauseTimer}
              className="flex items-center space-x-2 px-6 py-3 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
            >
              <Pause className="w-5 h-5" />
              <span>Pause</span>
            </button>
          )}

          <button
            onClick={resetTimer}
            className="flex items-center space-x-2 px-4 py-3 bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors"
          >
            <RotateCcw className="w-5 h-5" />
            <span>Reset</span>
          </button>

          <button
            onClick={skipSession}
            className="flex items-center space-x-2 px-4 py-3 bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors"
          >
            <Square className="w-5 h-5" />
            <span>Skip</span>
          </button>
        </div>
      </div>

      {/* Action Buttons */}
      <div className="flex justify-center space-x-4">
        <button
          onClick={() => setShowStats(!showStats)}
          className="flex items-center space-x-2 px-4 py-2 bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-200 rounded-lg hover:bg-blue-200 dark:hover:bg-blue-900/50 transition-colors"
        >
          <BarChart3 className="w-4 h-4" />
          <span>Statistics</span>
        </button>

        <button
          onClick={() => setShowSettings(!showSettings)}
          className="flex items-center space-x-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
        >
          <Settings className="w-4 h-4" />
          <span>Settings</span>
        </button>

        <button
          onClick={exportToExcel}
          className="flex items-center space-x-2 px-4 py-2 bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-200 rounded-lg hover:bg-green-200 dark:hover:bg-green-900/50 transition-colors"
        >
          <FileSpreadsheet className="w-4 h-4" />
          <span>Export</span>
        </button>
      </div>

      {/* Statistics Panel */}
      {showStats && (
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 space-y-6">
          <h3 className="text-xl font-bold text-gray-900 dark:text-white">Today's Statistics</h3>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-red-50 dark:bg-red-900/20 rounded-lg p-4">
              <div className="text-2xl font-bold text-red-800 dark:text-red-200">
                {todayStats.completedPomodoros}
              </div>
              <div className="text-sm text-red-600 dark:text-red-400">Completed Pomodoros</div>
            </div>

            <div className="bg-green-50 dark:bg-green-900/20 rounded-lg p-4">
              <div className="text-2xl font-bold text-green-800 dark:text-green-200">
                {Math.round(todayStats.totalFocusTime)}m
              </div>
              <div className="text-sm text-green-600 dark:text-green-400">Focus Time</div>
            </div>

            <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-4">
              <div className="text-2xl font-bold text-blue-800 dark:text-blue-200">
                {Math.round(todayStats.totalBreakTime)}m
              </div>
              <div className="text-sm text-blue-600 dark:text-blue-400">Break Time</div>
            </div>
          </div>

          {/* Recent Sessions */}
          {todayStats.sessions.length > 0 && (
            <div>
              <h4 className="font-medium text-gray-900 dark:text-white mb-3">Recent Sessions</h4>
              <div className="space-y-2 max-h-40 overflow-y-auto">
                {todayStats.sessions.slice(-5).reverse().map((session, index) => (
                  <div key={index} className="flex items-center justify-between bg-gray-50 dark:bg-gray-700 rounded-lg p-3">
                    <div className="flex items-center space-x-3">
                      <div className={`w-3 h-3 rounded-full ${
                        session.type === 'work' ? 'bg-red-500' :
                        session.type === 'shortBreak' ? 'bg-green-500' : 'bg-blue-500'
                      }`}></div>
                      <span className="text-sm font-medium text-gray-900 dark:text-white">
                        {modeConfig[session.type].label}
                      </span>
                      {session.task && (
                        <span className="text-xs text-gray-600 dark:text-gray-400">
                          • {session.task}
                        </span>
                      )}
                    </div>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      {new Date(session.completedAt).toLocaleTimeString()}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Settings Panel */}
      {showSettings && (
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 space-y-6">
          <h3 className="text-xl font-bold text-gray-900 dark:text-white">Settings</h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Duration Settings */}
            <div className="space-y-4">
              <h4 className="font-medium text-gray-900 dark:text-white">Duration (minutes)</h4>

              <div className="space-y-3">
                <div>
                  <label className="block text-sm text-gray-600 dark:text-gray-400 mb-1">
                    Work Session
                  </label>
                  <input
                    type="number"
                    min="1"
                    max="120"
                    value={settings.workDuration}
                    onChange={(e) => setSettings(prev => ({ ...prev, workDuration: parseInt(e.target.value) }))}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-sm text-gray-600 dark:text-gray-400 mb-1">
                    Short Break
                  </label>
                  <input
                    type="number"
                    min="1"
                    max="60"
                    value={settings.shortBreakDuration}
                    onChange={(e) => setSettings(prev => ({ ...prev, shortBreakDuration: parseInt(e.target.value) }))}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-sm text-gray-600 dark:text-gray-400 mb-1">
                    Long Break
                  </label>
                  <input
                    type="number"
                    min="1"
                    max="120"
                    value={settings.longBreakDuration}
                    onChange={(e) => setSettings(prev => ({ ...prev, longBreakDuration: parseInt(e.target.value) }))}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-sm text-gray-600 dark:text-gray-400 mb-1">
                    Pomodoros until Long Break
                  </label>
                  <input
                    type="number"
                    min="2"
                    max="10"
                    value={settings.pomodorosUntilLongBreak}
                    onChange={(e) => setSettings(prev => ({ ...prev, pomodorosUntilLongBreak: parseInt(e.target.value) }))}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>
              </div>
            </div>

            {/* Behavior Settings */}
            <div className="space-y-4">
              <h4 className="font-medium text-gray-900 dark:text-white">Behavior</h4>

              <div className="space-y-3">
                <label className="flex items-center space-x-3">
                  <input
                    type="checkbox"
                    checked={settings.autoStartBreaks}
                    onChange={(e) => setSettings(prev => ({ ...prev, autoStartBreaks: e.target.checked }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">
                    Auto-start break sessions
                  </span>
                </label>

                <label className="flex items-center space-x-3">
                  <input
                    type="checkbox"
                    checked={settings.autoStartWork}
                    onChange={(e) => setSettings(prev => ({ ...prev, autoStartWork: e.target.checked }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">
                    Auto-start work sessions
                  </span>
                </label>

                <label className="flex items-center space-x-3">
                  <input
                    type="checkbox"
                    checked={settings.notifications}
                    onChange={(e) => setSettings(prev => ({ ...prev, notifications: e.target.checked }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">
                    Browser notifications
                  </span>
                </label>

                <label className="flex items-center space-x-3">
                  <input
                    type="checkbox"
                    checked={settings.sounds}
                    onChange={(e) => setSettings(prev => ({ ...prev, sounds: e.target.checked }))}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">
                    Sound notifications
                  </span>
                </label>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Task Management */}
      <div className="bg-white dark:bg-gray-800 rounded-xl p-6 space-y-4">
        <h3 className="text-xl font-bold text-gray-900 dark:text-white">Tasks</h3>

        {/* Add Task */}
        <div className="flex space-x-2">
          <input
            type="text"
            placeholder="Add a new task..."
            value={newTask}
            onChange={(e) => setNewTask(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && addTask()}
            className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
          />
          <button
            onClick={addTask}
            className="px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 transition-colors"
          >
            Add
          </button>
        </div>

        {/* Task List */}
        <div className="space-y-2 max-h-60 overflow-y-auto">
          {tasks.map(task => (
            <div key={task.id} className="flex items-center space-x-3 bg-gray-50 dark:bg-gray-700 rounded-lg p-3">
              <input
                type="checkbox"
                checked={task.completed}
                onChange={() => toggleTask(task.id)}
                className="rounded border-gray-300 text-orange-600 focus:ring-orange-500"
              />
              <span
                className={`flex-1 cursor-pointer ${
                  task.completed
                    ? 'line-through text-gray-500 dark:text-gray-400'
                    : 'text-gray-900 dark:text-white'
                }`}
                onClick={() => !task.completed && setCurrentTask(task.text)}
              >
                {task.text}
              </span>
              {currentTask === task.text && (
                <span className="text-xs bg-orange-100 dark:bg-orange-900/30 text-orange-800 dark:text-orange-200 px-2 py-1 rounded">
                  Active
                </span>
              )}
              <button
                onClick={() => deleteTask(task.id)}
                className="text-red-500 hover:text-red-700 transition-colors"
              >
                ×
              </button>
            </div>
          ))}

          {tasks.length === 0 && (
            <p className="text-center text-gray-500 dark:text-gray-400 py-8">
              No tasks yet. Add one above to get started!
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default PomodoroTimer;
