/**
 * Productivity.jsx
 * Productivity management page with Pomodoro timer and future productivity tools
 */

import React from 'react';
import { CheckSquare, Clock } from 'lucide-react';
import PomodoroTimer from '../components/PomodoroTimer';
import ModulePage from '../components/ModulePage';

const Productivity = ({ searchNavigation }) => {
  // Available productivity modules
  const productivityModules = [
    {
      id: 'pomodoro',
      title: 'Pomodoro Timer',
      description: 'Boost productivity with focused work sessions and strategic breaks using the proven Pomodoro Technique',
      icon: Clock,
      status: 'available',
      component: PomodoroTimer
    }
  ];

  return (
    <ModulePage
      title="Productivity Suite"
      icon={CheckSquare}
      modules={productivityModules}
      searchNavigation={searchNavigation}
      colorTheme="orange"
      eventPrefix="productivity_tool"
      buttonText="Launch Tool"
    />
  );
};

export default Productivity;
