import React, { Suspense, useEffect, useRef } from 'react';
import { Home, Calculator, DollarSign, TrendingUp, BarChart3 } from 'lucide-react';
import useFinancialFormulaSuite from '../../hooks/useFinancialFormulaSuite';

// Import static color theme references to ensure Tailwind keeps blue classes
const colorThemes = {
  blue: {
    border: 'border-blue-200 dark:border-blue-800',
    button: 'bg-blue-600 hover:bg-blue-700',
    glow: 'glow-blue',
    gradient: 'from-blue-500 to-blue-600',
    ring: 'ring-blue-500/30'
  }
};

/**
 * Financial Formula Suite - Main Application Component
 *
 * Features:
 * - Persistent horizontal tab bar on mobile (sticky under navbar)
 * - Desktop vertical tab navigation with glassmorphism styling
 * - Lazy-loaded tab content with Suspense
 * - Full keyboard navigation support (Arrow keys, Home/End)
 * - LocalStorage persistence of selected tab
 * - Analytics tracking for app usage
 */
export default function FinancialFormulaSuite() {
  const { selectedTab, selectTab, tabs, navigateTab, selectedTabData } = useFinancialFormulaSuite();
  const tabListRef = useRef(null);

  // Tab icons mapping
  const tabIcons = {
    home: Home,
    'compound-interest': Calculator,
    'present-value': DollarSign,
    'net-present-value': BarChart3
  };

  // Keyboard navigation handler
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (!tabListRef.current?.contains(document.activeElement)) return;

      switch (event.key) {
        case 'ArrowDown':
          event.preventDefault();
          navigateTab('next');
          break;
        case 'ArrowUp':
          event.preventDefault();
          navigateTab('prev');
          break;
        case 'Home':
          event.preventDefault();
          navigateTab('first');
          break;
        case 'End':
          event.preventDefault();
          navigateTab('last');
          break;
        case 'Enter':
        case ' ':
          event.preventDefault();
          // Tab is already selected by focus, no additional action needed
          break;
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [navigateTab]);

  // Render the selected tab content with lazy loading
  const renderTabContent = () => {
    if (!selectedTabData) return <div>Tab not found</div>;

    const LazyComponent = React.lazy(selectedTabData.load);

    return (
      <Suspense
        fallback={
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
            <span className="ml-3 text-gray-600 dark:text-gray-400">Loading...</span>
          </div>
        }
      >
        <LazyComponent />
      </Suspense>
    );
  };

  return (
    <>
      {/* Fixed Mobile Tab Bar - Always visible at top of screen under main navbar */}
      <div className="lg:hidden fixed top-16 left-0 right-0 z-50 bg-white/90 dark:bg-gray-900/90 backdrop-blur-md border-b border-gray-200/30 dark:border-gray-700/30 shadow-sm">
        <nav aria-label="Financial Formula Suite Navigation" className="max-w-7xl mx-auto px-4">
          <div
            role="tablist"
            className="flex gap-2 overflow-x-auto scrollbar-hide py-3"
            aria-orientation="horizontal"
            style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
          >
            {tabs.map((tab) => {
              const Icon = tabIcons[tab.id] || Calculator;
              const isSelected = tab.id === selectedTab;

              return (
                <button
                  key={tab.id}
                  role="tab"
                  tabIndex={isSelected ? 0 : -1}
                  aria-selected={isSelected}
                  aria-controls={`panel-${tab.id}`}
                  onClick={() => selectTab(tab.id)}
                  className={`
                    flex items-center gap-2 px-4 py-2 rounded-lg whitespace-nowrap flex-shrink-0
                    font-light tracking-wide transition-all duration-200
                    focus:outline-none focus:ring-2 focus:ring-red-500/30
                    ${isSelected
                      ? 'bg-red-500 text-white shadow-lg shadow-red-500/25'
                      : 'bg-white/70 dark:bg-gray-800/70 text-gray-700 dark:text-gray-300 hover:bg-red-50 dark:hover:bg-red-900/20 hover:text-red-600 dark:hover:text-red-400'
                    }
                  `}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span className="text-sm font-medium">{tab.title}</span>
                </button>
              );
            })}
          </div>
        </nav>
      </div>

      {/* Main Container with minimal top padding to account for fixed tab bar */}
      <div className="max-w-7xl mx-auto pt-4 lg:pt-0">
        {/* Main Layout */}
        <div className="flex flex-col lg:flex-row gap-6">
          {/* Left Navigation - Vertical Tabs (Desktop Only) */}
          <nav
            className="hidden lg:block w-56 flex-shrink-0"
            aria-label="Financial Formula Suite Navigation"
          >
            <div className="sticky top-4 p-4 rounded-2xl bg-white/5 dark:bg-black/30 backdrop-blur-md border border-white/10">
              <ul
                ref={tabListRef}
                role="tablist"
                className="space-y-2"
                aria-orientation="vertical"
              >
                {tabs.map((tab) => {
                  const Icon = tabIcons[tab.id] || Calculator;
                  const isSelected = tab.id === selectedTab;

                  return (
                    <li key={tab.id} role="none">
                      <button
                        role="tab"
                        tabIndex={isSelected ? 0 : -1}
                        aria-selected={isSelected}
                        aria-controls={`panel-${tab.id}`}
                        onClick={() => selectTab(tab.id)}
                        className={`
                          w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left
                          font-light tracking-wide transition-all duration-200
                          focus:outline-none focus:ring-2 focus:ring-red-500/30
                          ${isSelected
                            ? 'bg-gradient-to-r from-red-500/20 to-red-600/20 text-red-600 dark:text-red-400 glow-red border border-red-200/30'
                            : 'text-gray-700 dark:text-gray-300 hover:bg-white/5 hover:text-red-600 dark:hover:text-red-400'
                          }
                        `}
                      >
                        <Icon className="w-5 h-5 flex-shrink-0" />
                        <span className="truncate">{tab.title}</span>
                      </button>
                    </li>
                  );
                })}
              </ul>
            </div>
          </nav>

          {/* Content Area */}
          <main className="flex-1 min-w-0">
            <div
              id={`panel-${selectedTab}`}
              role="tabpanel"
              tabIndex={0}
              aria-labelledby={`tab-${selectedTab}`}
              className="p-8 rounded-2xl bg-white/5 dark:bg-black/30 backdrop-blur-md border border-white/10 min-h-[600px] focus:outline-none focus:ring-2 focus:ring-red-500/30"
            >
              {renderTabContent()}
            </div>
          </main>
        </div>
      </div>
    </>
  );
}
